import{_ as a,o as n,c as r,a5 as t}from"./chunks/framework.DGp912Ge.js";const p=JSON.parse('{"title":"Operating Environment Requirements","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety/operating-environment-requirements.md","filePath":"manual/safety/operating-environment-requirements.md","lastUpdated":1785806273000}'),o={name:"manual/safety/operating-environment-requirements.md"};function s(i,e,l,d,m,c){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="operating-environment-requirements" tabindex="-1">Operating Environment Requirements <a class="header-anchor" href="#operating-environment-requirements" aria-label="Permalink to &quot;Operating Environment Requirements&quot;">​</a></h1><p>The RBQ is a quadruped robot used in <strong>various environments</strong>-indoors, general workshops, hazardous sites, military use, patrol/inspection, etc.</p><ul><li><strong>Below</strong>: Recommended conditions for general use and specification limits.</li><li><strong>Special environments</strong> (hazardous workplaces, military, unmanned patrol, etc.) may require separate risk assessments and additional measures.</li></ul><h2 id="recommended-environment-general-use" tabindex="-1">Recommended environment (general use) <a class="header-anchor" href="#recommended-environment-general-use" aria-label="Permalink to &quot;Recommended environment (general use)&quot;">​</a></h2><p>The following are recommended for normal operation and service life. Performance and warranty apply when these are met.</p><h3 id="temperature-and-humidity" tabindex="-1">Temperature and humidity <a class="header-anchor" href="#temperature-and-humidity" aria-label="Permalink to &quot;Temperature and humidity&quot;">​</a></h3><ul><li><strong>Use and storage temperature</strong>: Stay within the operating and storage ranges stated in the manual or specifications. Outside those ranges you may get reduced performance, failure, or shorter battery life.</li><li><strong>Humidity</strong>: In very damp or condensing environments, sensors and electrical parts can be affected-use and store within the specified humidity range when possible.</li></ul><h3 id="floor-and-space" tabindex="-1">Floor and space <a class="header-anchor" href="#floor-and-space" aria-label="Permalink to &quot;Floor and space&quot;">​</a></h3><ul><li><strong>Flatness</strong>: The robot is most stable on flat, solid floors within the specified limits. On steep slopes, rough terrain, or slippery surfaces it may fall or become unstable.</li><li><strong>Space</strong>: Provide enough room for movement, posture correction, and recovery from falls. <strong>While operating, no people or animals (including pets) may enter within 2 m of the robot.</strong> Keep safe clearance from obstacles as well.</li></ul><h3 id="electromagnetic-and-physical-environment" tabindex="-1">Electromagnetic and physical environment <a class="header-anchor" href="#electromagnetic-and-physical-environment" aria-label="Permalink to &quot;Electromagnetic and physical environment&quot;">​</a></h3><ul><li><strong>Magnetic fields</strong>: Strong fields can affect sensors and control-avoid use when possible.</li><li><strong>Vibration and shock</strong>: Excessive vibration or shock can cause failure or bad measurements-damp or isolate, or limit use.</li></ul><h3 id="hazardous-environments" tabindex="-1">Hazardous environments <a class="header-anchor" href="#hazardous-environments" aria-label="Permalink to &quot;Hazardous environments&quot;">​</a></h3><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Do not use in explosive atmospheres, flammable gas, or heavy dust. If no IP rating is stated, <strong>do not use</strong> outdoors, in rain, or near water features (use is prohibited).</p></div></div><h2 id="use-in-special-or-marginal-environments" tabindex="-1">Use in special or marginal environments <a class="header-anchor" href="#use-in-special-or-marginal-environments" aria-label="Permalink to &quot;Use in special or marginal environments&quot;">​</a></h2><p>In hazardous workplaces, military use, unmanned patrol, disaster sites, or hard-to-access inspections, <strong>temperature, humidity, floor, and space</strong> may not meet specification, and unpredictable hazards may exist.<br> If you use the RBQ for such purposes, perform a <strong>risk assessment before use</strong> and apply <strong>additional safety devices, procedures, and PPE</strong> as needed. Warranty may not apply to failures or damage from use outside the specified environment.</p><p>Contact Rainbow Robotics if needed. See <a href="/RBQ/manual/troubleshooting/error-reporting.html">Contact / Error Reporting</a>.</p>',16)])])}const h=a(o,[["render",s]]);export{p as __pageData,h as default};
